			byte[] prefix = "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"T\",\"lex\":\"".getBytes(StandardCharsets.UTF_8);
			byte[] suffix = "\",\"dt\":\"\",\"lang\":\"\",\"hash\":0}\n".getBytes(StandardCharsets.UTF_8);
